import sys

data = sys.stdin.read().split()
n, k = int(data[0]), int(data[1])
a = [int(x) for x in data[2:2 + n]]
dp = [1] * n
for i in range(n):
    for j in range(i):
        if 0 < a[i] - a[j] <= k and dp[j] + 1 > dp[i]:
            dp[i] = dp[j] + 1
print(max(dp))

